import React from "react";

const StatCard = ({ icon: Icon, title, value, change, color }) => {
  // Sécurisation des données
  const safeTitle = title ?? "Non défini";
  const safeValue = Number(value) || 0;
  const safeChange = Number(change);

  const hasChange = change !== undefined && change !== null && !isNaN(safeChange);

  return (
    <div className="bg-white rounded-xl p-6 shadow-md border border-gray-100 hover:shadow-lg transition duration-200">
      <div className="flex items-center justify-between">

        <div>
          {/* Titre */}
          <p className="text-sm text-gray-600 mb-1">{safeTitle}</p>

          {/* Valeur */}
          <p className="text-2xl font-bold text-gray-900">{safeValue}</p>

          {/* Variation (change) */}
          {hasChange && (
            <p
              className={`text-sm ${
                safeChange > 0 ? "text-green-600" : "text-red-600"
              } mt-1 flex items-center`}
            >
              {safeChange > 0 ? (
                <span className="mr-1">↗</span>
              ) : (
                <span className="mr-1">↘</span>
              )}
              {Math.abs(safeChange)}% vs mois dernier
            </p>
          )}
        </div>

        {/* Icône protégée */}
        <div className={`p-3 rounded-lg ${color || "bg-gray-400"} shadow-md`}>
          {Icon ? (
            <Icon className="h-6 w-6 text-white" />
          ) : (
            <span className="text-white text-lg">?</span>
          )}
        </div>
      </div>
    </div>
  );
};

export default StatCard;
